#!/usr/bin/env node

// plank-join.mjs — Shipshape plank-join checker.
//
// Scans implementation directories for @planks(...) and @planks-provisional(...)
// annotations in docblocks.  Cross-references each @planks string against current
// step-definition patterns and each @planks-provisional reference against @captain
// scenarios in the features directory.
//
// Exits 0 when every plank conforms.  Exits non-zero with a report on stderr
// for each broken plank.

import * as fs from 'node:fs';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(fileURLToPath(import.meta.url), '..', '..');
const IMPL_DIRS = ['js'];
const SPECS_DIR = 'features';

// ---- Helpers ---------------------------------------------------------------

function* walkFiles(dir) {
  if (!fs.statSync(dir, { throwIfNoEntry: false })) return;
  const entries = fs.readdirSync(dir, { withFileTypes: true });
  for (const e of entries) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) {
      if (!e.name.startsWith('.') && e.name !== 'node_modules') yield* walkFiles(p);
    } else if (e.isFile() && (e.name.endsWith('.js') || e.name.endsWith('.mjs') || e.name.endsWith('.cjs'))) {
      yield p;
    }
  }
}

// Extract @planks and @planks-provisional tokens from a file.  We look for the
// pattern inside /** */ docblocks (Perl-style regex to keep this self-contained).
const PLANKS_RE = /@planks\(["']([^"']+)["']\)/g;
const PROVISIONAL_RE = /@planks-provisional\(["']([^"']+)["']\)/g;

function extractPlanks(source, filePath) {
  const planks = [];
  const provisionals = [];
  let m;

  // Reset regex state
  PLANKS_RE.lastIndex = 0;
  PROVISIONAL_RE.lastIndex = 0;

  while ((m = PLANKS_RE.exec(source)) !== null) planks.push(m[1]);
  while ((m = PROVISIONAL_RE.exec(source)) !== null) provisionals.push(m[1]);

  return { planks, provisionals };
}

// Gather step-definition patterns from features/support and features/step_definitions.
// A step definition is a call to Given / When / Then / And / But with a string pattern.
const STEP_RE = /(?:Given|When|Then|And|But)\s*\(\s*["'`]((?:[^"'`]|\\.)*)["'`]/g;

function collectStepPatterns() {
  const patterns = new Set();
  const supportDir = path.join(ROOT, SPECS_DIR, 'support');
  const stepsDir = path.join(ROOT, SPECS_DIR, 'step_definitions');

  for (const d of [supportDir, stepsDir]) {
    for (const f of walkFiles(d)) {
      const src = fs.readFileSync(f, 'utf8');
      STEP_RE.lastIndex = 0;
      let m;
      while ((m = STEP_RE.exec(src)) !== null) patterns.add(m[1]);
    }
  }
  return patterns;
}

// Gather @captain scenario names from feature files.
const CAPTAIN_SCENARIO_RE = /@captain\s*\n\s*Scenario:\s*(.+)$/gm;

function collectCaptainScenarios() {
  const names = new Set();
  const specsDir = path.join(ROOT, SPECS_DIR);
  for (const f of walkFiles(specsDir)) {
    if (!f.endsWith('.feature')) continue;
    const src = fs.readFileSync(f, 'utf8');
    CAPTAIN_SCENARIO_RE.lastIndex = 0;
    let m;
    while ((m = CAPTAIN_SCENARIO_RE.exec(src)) !== null) names.add(m[1].trim());
  }
  return names;
}

// Resolve a provisional reference like "features/todos.feature:Create a todo" to
// just the scenario name part.
function provisionalScenarioName(ref) {
  const idx = ref.indexOf(':');
  return idx === -1 ? ref.trim() : ref.slice(idx + 1).trim();
}

// ---- Main ------------------------------------------------------------------

const stepPatterns = collectStepPatterns();
const captainScenarios = collectCaptainScenarios();

let errors = [];

for (const implDir of IMPL_DIRS) {
  const absDir = path.join(ROOT, implDir);
  for (const f of walkFiles(absDir)) {
    const src = fs.readFileSync(f, 'utf8');
    const { planks, provisionals } = extractPlanks(src);
    const rel = path.relative(ROOT, f);

    for (const p of planks) {
      if (!stepPatterns.has(p)) {
        errors.push(`${rel}: @planks("${p}") matches no current step-definition pattern`);
      }
    }

    for (const p of provisionals) {
      const name = provisionalScenarioName(p);
      if (!captainScenarios.has(name)) {
        errors.push(`${rel}: @planks-provisional("${p}") names scenario "${name}" which no longer carries @captain`);
      }
    }
  }
}

if (errors.length > 0) {
  for (const e of errors) console.error(e);
  process.exit(1);
}

console.log('plank-join: all planks conform');
process.exit(0);

