  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Todo item",
  "description": "A single todo item stored in localStorage",
  "type": "object",
  "required": ["id", "title", "completed"],
  "properties": {
    "id": {
      "description": "Unique identifier for the todo item",
      "type": "string"
    },
    "title": {
      "description": "The todo item's display text",
      "type": "string",
      "minLength": 1
    },
    "completed": {
      "description": "Whether the todo item is marked complete",
      "type": "boolean"
    }
  },
  "additionalProperties": false
}

