function extractPlanks(source) {
	const planks = [];
	const provisionals = [];

	// Reset regex state
	PLANKS_RE.lastIndex = 0;
	PROVISIONAL_RE.lastIndex = 0;

	for (;;) {
		const m = PLANKS_RE.exec(source);
		if (m === null) break;
		planks.push(m[1]);
	}
	for (;;) {
		const m = PROVISIONAL_RE.exec(source);
		if (m === null) break;
		provisionals.push(m[1]);
	}

	return { planks, provisionals };
}

